with a as(select * from public.authors where open_library_id=any(array['OL231796A','OL289798A']::text[]) or id=any(array[3477,2914]::bigint[])) select jsonb_build_object('checked_at',clock_timestamp(),'authors',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from a t),'author_corpora',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.works t where author_id in(select id from a)),'isbn_matches',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.editions t where regexp_replace(coalesce(isbn_13,''),'[-[:space:]]','','g')=any(array['9789022990056','9789029526746']::text[])),'source_work_matches',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.works t where open_library_id=any(array['OL1932332W','OL2240620W']::text[])),'title_matches',(select coalesce(jsonb_agg(jsonb_build_object('relation','works','row',to_jsonb(t))),'[]') from public.works t where regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['thestatuscivilization','destatusplaneetbrunosciencefiction5','destatusplaneet','debuitenkant']::text[])),'edition_title_matches',(select coalesce(jsonb_agg(jsonb_build_object('relation','editions','row',to_jsonb(t))),'[]') from public.editions t where regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['thestatuscivilization','destatusplaneetbrunosciencefiction5','destatusplaneet','debuitenkant']::text[])),'reserved_test_ranges',jsonb_build_object('works',(select count(*) from public.works where id between 987161001 and 987161999),'editions',(select count(*) from public.editions where id between 987261001 and 987261999),'authors',(select count(*) from public.authors where id between 987361001 and 987361999))) as preflight;
